scwin.grid1_ongroupby = function(options) {
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
	return false;
}
// 필터 목록이 그리드 안(높이 내)에 들어오고, 목록에 세로 스크롤이 생겨 모든 항목에 접근 가능한지
scwin.checkVal = function() {
	var sv = document.getElementById('mf_grid1_customFilter_scrollView') || document.getElementById('grid1_customFilter_scrollView');
	var list = document.getElementById('mf_grid1_customFilter_list') || document.getElementById('grid1_customFilter_list');
	var g = (document.getElementById('mf_grid1') || document.getElementById('grid1')).getBoundingClientRect();
	var r = sv.getBoundingClientRect();
	return r.height > 0 && r.bottom <= g.bottom + 1 && list.scrollHeight > list.clientHeight && getComputedStyle(list).overflowY != 'hidden';
}
scwin.checkVal2 = function() {
	return scwin.__getJq($('.w2grid_groupbyZone_list_listColumn_text').last()).text() == '9';
}
